WITH catalog_total AS (SELECT COUNT(DISTINCT product_id) AS total_products FROM fashion.catalog.products) SELECT p.master_category AS master_category, COUNT(DISTINCT p.product_id) AS product_count, ROUND(100.0 * COUNT(DISTINCT p.product_id) / t.total_products, 2) AS catalog_share_pct, COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END) AS distinct_base_colours, CASE WHEN COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END) = 0 THEN NULL ELSE ROUND(COUNT(DISTINCT p.product_id) * 1.0 / COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END), 1) END AS products_per_colour FROM fashion.catalog.products p CROSS JOIN catalog_total t WHERE p.master_category IS NOT NULL AND TRIM(p.master_category) <> '' AND p.product_id IS NOT NULL GROUP BY p.master_category, t.total_products ORDER BY product_count DESC, p.master_category ASC
